/* AGPL-3.0-or-later. Runs model inference away from the camera UI. */
importScripts('vendor/ort.wasm.min.js');
let session,loading,queue=Promise.resolve();
async function init(){if(session)return;if(loading)return loading;loading=(async()=>{ort.env.wasm.numThreads=1;ort.env.wasm.wasmPaths=new URL('vendor/',self.location.href).href;const r=await fetch('model/manifest.json');if(!r.ok)throw Error('모델 정보를 읽을 수 없습니다');const meta=await r.json(),bytes=new Uint8Array(meta.size);let offset=0;for(let i=0;i<meta.parts.length;i++){postMessage({progress:`모기 AI 다운로드 ${i+1}/${meta.parts.length} · 처음 약 60 MB`});const r=await fetch('model/'+meta.parts[i]);if(!r.ok)throw Error('모델 다운로드 실패');const a=new Uint8Array(await r.arrayBuffer());bytes.set(a,offset);offset+=a.length}if(offset!==meta.size)throw Error('모델 크기 불일치');postMessage({progress:'모기 AI 준비 중'});session=await ort.InferenceSession.create(bytes,{executionProviders:['wasm'],graphOptimizationLevel:'all'})})().catch(e=>{loading=null;throw e});return loading}
onmessage=e=>{const msg=e.data;queue=queue.then(async()=>{try{await init();if(msg.type==='init'){postMessage({id:msg.id,ok:true});return}const input=new ort.Tensor('float32',msg.input,[1,3,640,640]);let result;try{result=await session.run({[session.inputNames[0]]:input});const out=result[session.outputNames[0]];if(out.dims.length!==3||out.dims[1]!==5)throw Error('모델 출력 형식 불일치');const data=new Float32Array(out.data);postMessage({id:msg.id,data,count:out.dims[2]},[data.buffer])}finally{input.dispose?.();if(result)Object.values(result).forEach(t=>t.dispose?.())}}catch(e){postMessage({id:msg.id,error:e.message||String(e)})}})};
